const _fnd=document.getElementById('finder');if(_fnd)_fnd.addEventListener('submit',e=>{
  e.preventDefault();
  const city=document.getElementById('q-city').value,type=document.getElementById('q-type').value,[lo,hi]=document.getElementById('q-days').value.split('-').map(Number);
  try{sessionStorage.setItem('rmtFind',JSON.stringify([city,type,lo,hi]))}catch(x){}
  go(type);
  setTimeout(()=>{
    document.querySelectorAll('.trow.hit').forEach(r=>r.classList.remove('hit'));
    if(type==='custom-tours'){
      const f=document.getElementById('f-from');if(f)f.value=city;
      const r=document.getElementById('request');if(r)r.scrollIntoView();return;
    }
    const g=document.querySelector('[data-view="'+type+'"] .cg[data-city="'+city+'"]');
    if(!g)return;
    g.querySelectorAll('.trow').forEach(r=>{const d=+r.dataset.d;if(d>=lo&&d<=hi)r.classList.add('hit')});
    g.scrollIntoView({block:'center'});
  },60);
});

